1	export type Customer = { yearsWithMHPCO: number };
2	
3	export type Scenario = {
4	  customer: Customer;
5	  steps: Step[];
6	};
7	
8	export type Step =
9	  | { op: "quote"; items: Item[] }
10	  | { op: "claim"; policy: number; incident: Incident };
11	
12	export type Item = {
13	  type: string;
14	  material?: string;
15	  enchantment?: number;
16	  cursed?: boolean;
17	};
18	
19	export type Incident = {
20	  cause: string;
21	  damages: Damage[];
22	};
23	
24	export type Damage = {
25	  itemType: string;
26	  amount: number;
27	};
28	
29	export type Result = { premium: number } | { payout: number; remainingCap: number };
30	
31	const PROCESSING_FEE = 5;
32	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
33	
34	// The catalogue of insurable item types. Each type carries both figures the
35	// office needs: what it costs to insure (base premium) and what it is worth
36	// when destroyed (insurance value). Keeping them in one row means a new item
37	// type is one edit, and the two figures can never drift apart.
38	const CATALOGUE: Record<string, { basePremium: number; insuranceValue: number }> = {
39	  sword: { basePremium: 100, insuranceValue: 1000 },
40	  amulet: { basePremium: 60, insuranceValue: 600 },
41	  staff: { basePremium: 80, insuranceValue: 800 },
42	  potion: { basePremium: 40, insuranceValue: 400 },
43	  rune: { basePremium: 25, insuranceValue: 250 },
44	  moonstone: { basePremium: 25, insuranceValue: 250 },
45	};
46	
47	// Both catalogue figures are read through this one row lookup, so an item's type
48	// is resolved against the catalogue in exactly one place.
49	const catalogueEntryFor = (item: Item) => {
50	  const entry = CATALOGUE[item.type];
51	  if (entry === undefined) {
52	    throw new Error(`the MHPCO does not insure items of type "${item.type}"`);
53	  }
54	  return entry;
55	};
56	
57	// Totalling a catalogue column over a list of items is the same operation on the
58	// premium side and the claim side; only the column differs. Naming it once keeps
59	// the two columns visibly separate — which is the point: the building-block
60	// discount rewrites the basePremium column and never touches insuranceValue.
61	const totalOfColumn =
62	  (columnOf: (item: Item) => number) =>
63	  (items: Item[]): number =>
64	    items.reduce((total, item) => total + columnOf(item), 0);
65	
66	const basePremiumOf = (item: Item): number => catalogueEntryFor(item).basePremium;
67	
68	const BLOCK_SIZE = 3;
69	const BLOCK_BASE_PREMIUM = 60;
70	
71	const formsABuildingBlock = (alikeItems: Item[]): boolean =>
72	  alikeItems.length === BLOCK_SIZE;
73	
74	const sumOfBasePremiums = totalOfColumn(basePremiumOf);
75	
76	const CURSE_SURCHARGE_RATE = 0.5;
77	const HIGH_ENCHANTMENT_LEVEL = 5;
78	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
79	
80	const isCursed = (item: Item): boolean => item.cursed === true;
81	
82	// An unenchanted item is enchantment 0, so every threshold reads the level the
83	// same way. The MHPCO sets several enchantment thresholds for different rules;
84	// each names its own level and compares through here.
85	const enchantmentLevelOf = (item: Item): number => item.enchantment ?? 0;
86	
87	const carriesEnchantmentSurcharge = (item: Item): boolean =>
88	  enchantmentLevelOf(item) >= HIGH_ENCHANTMENT_LEVEL;
89	
90	// A rate table prices one subject: every row whose risk applies contributes its
91	// rate, and the total is their sum. Both the item surcharges and the policy-wide
92	// modifiers are rate tables — they differ only in what they are applied to.
93	type RateTable<Subject> = { appliesTo: (subject: Subject) => boolean; rate: number }[];
94	
95	const totalRateFrom = <Subject,>(table: RateTable<Subject>, subject: Subject): number =>
96	  table.reduce((total, row) => (row.appliesTo(subject) ? total + row.rate : total), 0);
97	
98	// Every item-specific surcharge is a rate on THAT item's base premium, charged
99	// when its risk applies. Adding a new one means adding a row here — nothing else.
100	const ITEM_SURCHARGES: RateTable<Item> = [
101	  { appliesTo: isCursed, rate: CURSE_SURCHARGE_RATE },
102	  { appliesTo: carriesEnchantmentSurcharge, rate: HIGH_ENCHANTMENT_SURCHARGE_RATE },
103	];
104	
105	const surchargeRateOn = (item: Item): number => totalRateFrom(ITEM_SURCHARGES, item);
106	
107	const itemSurchargesOn = (items: Item[]): number =>
108	  items.reduce((sum, item) => sum + basePremiumOf(item) * surchargeRateOn(item), 0);
109	
110	// Items of the same type are "alike"; each group is priced together so a
111	// building block can be recognised.
112	const alikeItemGroupsIn = (items: Item[]): Item[][] => [
113	  ...items
114	    .reduce(
115	      (groups, item) => groups.set(item.type, [...(groups.get(item.type) ?? []), item]),
116	      new Map<string, Item[]>(),
117	    )
118	    .values(),
119	];
120	
121	const basePremiumOfAlikeItems = (alikeItems: Item[]): number =>
122	  formsABuildingBlock(alikeItems) ? BLOCK_BASE_PREMIUM : sumOfBasePremiums(alikeItems);
123	
124	const policyBaseOf = (items: Item[]): number =>
125	  alikeItemGroupsIn(items).reduce(
126	    (sum, alikeItems) => sum + basePremiumOfAlikeItems(alikeItems),
127	    0,
128	  );
129	
130	// Rounding always favours the MHPCO. Which direction that is follows from which
131	// way the money moves: an amount the office RECEIVES is rounded up, an amount it
132	// PAYS is rounded down. Naming the two directions makes the rule one concept
133	// rather than two opposite-looking halves, and each call site says which kind of
134	// amount it holds — so the reason for the direction is in the code, not a comment.
135	const settledAsReceived = Math.ceil;
136	const settledAsPaid = Math.floor;
137	
138	const LOYALTY_YEARS = 2;
139	const LOYALTY_DISCOUNT_RATE = -0.2;
140	
141	const FOLLOW_UP_CONTRACT_DISCOUNT_RATE = -0.15;
142	
143	// Each item in a quote is treated as a first insurance regardless of customer
144	// history, so this surcharge is unconditional.
145	const appliesUnconditionally = (): boolean => true;
146	
147	const isLongStanding = ({ customer }: QuoteContext): boolean =>
148	  customer.yearsWithMHPCO >= LOYALTY_YEARS;
149	
150	const isFollowUpContract = ({ precedingQuotes }: QuoteContext): boolean =>
151	  precedingQuotes > 0;
152	
153	// A quote is priced from the customer plus its place in the scenario's history.
154	type QuoteContext = { customer: Customer; precedingQuotes: number };
155	
156	// Every policy-wide modifier is a rate on the UNMODIFIED policy base — never on a
157	// base that already includes the item surcharges. Surcharges carry a positive
158	// rate, discounts a negative one. Adding a new one means adding a row here.
159	const POLICY_MODIFIERS: RateTable<QuoteContext> = [
160	  { appliesTo: appliesUnconditionally, rate: FIRST_INSURANCE_SURCHARGE_RATE },
161	  { appliesTo: isLongStanding, rate: LOYALTY_DISCOUNT_RATE },
162	  { appliesTo: isFollowUpContract, rate: FOLLOW_UP_CONTRACT_DISCOUNT_RATE },
163	];
164	
165	const policyModifiersOn = (policyBase: number, context: QuoteContext): number =>
166	  policyBase * totalRateFrom(POLICY_MODIFIERS, context);
167	
168	const quoteFor = (items: Item[], context: QuoteContext): Result => {
169	  const policyBase = policyBaseOf(items);
170	  const riskAdjustedBase = policyBase + itemSurchargesOn(items);
171	  return {
172	    premium: settledAsReceived(
173	      riskAdjustedBase + policyModifiersOn(policyBase, context) + PROCESSING_FEE,
174	    ),
175	  };
176	};
177	
178	const DEDUCTIBLE_PER_DAMAGE = 100;
179	const CAP_MULTIPLE_OF_INSURANCE_SUM = 2;
180	
181	const insuranceValueOf = (item: Item): number => catalogueEntryFor(item).insuranceValue;
182	
183	// The insurance sum totals the value column over every insured item — one item,
184	// one row, no grouping. Blocks are a premium concept and cannot reach it.
185	const insuranceSumOf = totalOfColumn(insuranceValueOf);
186	
187	// A policy created by a quote step, tracked by that step's index so later claims
188	// can find it and draw down its cap.
189	type Policy = { items: Item[]; remainingCap: number };
190	
191	const policyFor = (items: Item[]): Policy => ({
192	  items,
193	  remainingCap: insuranceSumOf(items) * CAP_MULTIPLE_OF_INSURANCE_SUM,
194	});
195	
196	const HALF_REIMBURSEMENT_ENCHANTMENT_LEVEL = 8;
197	const HALF_REIMBURSEMENT_RATE = 0.5;
198	const FULL_REIMBURSEMENT_RATE = 1;
199	
200	// A distinct rule from the premium's HIGH_ENCHANTMENT_LEVEL, at a distinct
201	// level: this one halves what a claim pays out, that one raises what a policy
202	// costs. They move independently — deliberately not shared.
203	const reimbursesOnlyHalf = (item: Item): boolean =>
204	  enchantmentLevelOf(item) >= HALF_REIMBURSEMENT_ENCHANTMENT_LEVEL;
205	
206	// How much of the damage the MHPCO reimburses, before the deductible bites.
207	const reimbursementRateFor = (item: Item): number =>
208	  reimbursesOnlyHalf(item) ? HALF_REIMBURSEMENT_RATE : FULL_REIMBURSEMENT_RATE;
209	
210	// A damage names only an item TYPE, so it can identify no more than the type of
211	// the item it refers to; this returns the first insured item of that type as the
212	// representative whose traits price the damage.
213	//
214	// UNTESTED ASSUMPTION: that the first match is the right representative. Where a
215	// policy holds several alike items, the suite never distinguishes them — its only
216	// two-alike-items example insures two IDENTICAL swords, so first-match is
217	// unobservable there, and the spec offers no example pairing one type with
218	// DIFFERING enchantment or material. So this is an assumption the tests permit,
219	// not one they confirm. Should such an example appear, the damage would have to
220	// be matched to a specific item and this would be the place that changes.
221	const insuredItemOfType = (policy: Policy, damage: Damage): Item =>
222	  policy.items.find((item) => item.type === damage.itemType)!;
223	
224	const reimbursedAmountFor = (damage: Damage, policy: Policy): number =>
225	  damage.amount * reimbursementRateFor(insuredItemOfType(policy, damage));
226	
227	// The deductible bites once per damage, after the reimbursement rate is applied
228	// — never the other way round, which would pay out more.
229	const payoutForDamage = (damage: Damage, policy: Policy): number =>
230	  reimbursedAmountFor(damage, policy) - DEDUCTIBLE_PER_DAMAGE;
231	
232	// One incident can damage several items; each damage is settled on its own
233	// (and so bears its own deductible), and the incident pays out their sum.
234	const payoutForIncident = (incident: Incident, policy: Policy): number =>
235	  incident.damages.reduce((sum, damage) => sum + payoutForDamage(damage, policy), 0);
236	
237	// A payout is drawn from the policy's cap, leaving less for later claims.
238	const capDrawnDownBy = (policy: Policy, payout: number): Policy => ({
239	  ...policy,
240	  remainingCap: policy.remainingCap - payout,
241	});
242	
243	// The policy pays no more than the cap it has left, however large the damage.
244	const payoutWithinCapOf = (policy: Policy, desiredPayout: number): number =>
245	  Math.min(desiredPayout, policy.remainingCap);
246	
247	// Settling a claim pays out and draws the cap down by the same amount, so the
248	// result the customer sees is the payout plus the cap that payout left behind.
249	const claimFor = (incident: Incident, policy: Policy): [Result, Policy] => {
250	  const payout = settledAsPaid(
251	    payoutWithinCapOf(policy, payoutForIncident(incident, policy)),
252	  );
253	  const settledPolicy = capDrawnDownBy(policy, payout);
254	  return [{ payout, remainingCap: settledPolicy.remainingCap }, settledPolicy];
255	};
256	
257	// What the scenario has accumulated before the current step: the results so far,
258	// the history a quote is priced against, and the policies earlier quotes created.
259	type ScenarioState = {
260	  results: Result[];
261	  precedingQuotes: number;
262	  policies: Record<number, Policy>;
263	};
264	
265	const INITIAL_SCENARIO_STATE: ScenarioState = {
266	  results: [],
267	  precedingQuotes: 0,
268	  policies: {},
269	};
270	
271	// Every step reports exactly one result and leaves one policy at its index —
272	// the two things both step kinds always do. Recording them is named once here
273	// rather than rebuilt in each of them.
274	const withStepRecorded = (
275	  state: ScenarioState,
276	  result: Result,
277	  policyIndex: number,
278	  policy: Policy,
279	): ScenarioState => ({
280	  ...state,
281	  results: [...state.results, result],
282	  policies: { ...state.policies, [policyIndex]: policy },
283	});
284	
285	const afterQuote = (
286	  state: ScenarioState,
287	  items: Item[],
288	  customer: Customer,
289	  stepIndex: number,
290	): ScenarioState => ({
291	  ...withStepRecorded(
292	    state,
293	    quoteFor(items, { customer, precedingQuotes: state.precedingQuotes }),
294	    stepIndex,
295	    policyFor(items),
296	  ),
297	  precedingQuotes: state.precedingQuotes + 1,
298	});
299	
300	const afterClaim = (
301	  state: ScenarioState,
302	  policyIndex: number,
303	  incident: Incident,
304	): ScenarioState => {
305	  const [result, settledPolicy] = claimFor(incident, state.policies[policyIndex]);
306	  return withStepRecorded(state, result, policyIndex, settledPolicy);
307	};
308	
309	const afterStep = (
310	  state: ScenarioState,
311	  step: Step,
312	  customer: Customer,
313	  stepIndex: number,
314	): ScenarioState =>
315	  step.op === "quote"
316	    ? afterQuote(state, step.items, customer, stepIndex)
317	    : afterClaim(state, step.policy, step.incident);
318	
319	export const runScenario = (scenario: Scenario): { results: Result[] } => {
320	  const { results } = scenario.steps.reduce(
321	    (state, step, stepIndex) => afterStep(state, step, scenario.customer, stepIndex),
322	    INITIAL_SCENARIO_STATE,
323	  );
324	  return { results };
325	};
